import{_ as e,o as t,c as o,a2 as n}from"./chunks/framework.vLhlLNVn.js";const m=JSON.parse('{"title":"🔌 Model Context Protocol (MCP) 深度集成","description":"","frontmatter":{},"headers":[],"relativePath":"ai/mcp-protocol.md","filePath":"ai/mcp-protocol.md"}'),s={name:"ai/mcp-protocol.md"};function l(p,a,r,i,c,d){return t(),o("div",null,[...a[0]||(a[0]=[n(`<h1 id="🔌-model-context-protocol-mcp-深度集成" tabindex="-1">🔌 Model Context Protocol (MCP) 深度集成 <a class="header-anchor" href="#🔌-model-context-protocol-mcp-深度集成" aria-label="Permalink to &quot;🔌 Model Context Protocol (MCP) 深度集成&quot;">​</a></h1><p><a href="https://modelcontextprotocol.io/" target="_blank" rel="noreferrer">Model Context Protocol (MCP)</a> 是由 Anthropic 发起并被全球主流 AI 开发框架采纳的开放通信标准，用于安全地向大模型暴露工具、资源与上下文。</p><hr><h2 id="_1-mzmedia-中的-mcp-架构设计" tabindex="-1">1. MzMedia 中的 MCP 架构设计 <a class="header-anchor" href="#_1-mzmedia-中的-mcp-架构设计" aria-label="Permalink to &quot;1. MzMedia 中的 MCP 架构设计&quot;">​</a></h2><p>平台采用官方 Java MCP SDK (<code>io.modelcontextprotocol.client.McpSyncClient</code>) 构建客户端管理器，提供双通道连接模式：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span> ┌────────────────────────────────────────────────────────┐</span></span>
<span class="line"><span> │            Spring AI 智能中枢 (Ai1AgentService)        │</span></span>
<span class="line"><span> └───────────────────────────┬────────────────────────────┘</span></span>
<span class="line"><span>                             │ Tool Call 调度</span></span>
<span class="line"><span>                             ▼</span></span>
<span class="line"><span> ┌────────────────────────────────────────────────────────┐</span></span>
<span class="line"><span> │            MCP 客户端管理器 (Ai1McpClientManager)      │</span></span>
<span class="line"><span> ├────────────────────────────┬───────────────────────────┤</span></span>
<span class="line"><span> │ 1. stdio Transport         │ 2. http Transport         │</span></span>
<span class="line"><span> │ (本地子进程: Python/Node)  │ (远程 Streamable HTTP/SSE)│</span></span>
<span class="line"><span> └────────────────────────────┴───────────────────────────┘</span></span></code></pre></div><h3 id="传输通道一-stdio-transport" tabindex="-1">传输通道一：<code>stdio</code> Transport <a class="header-anchor" href="#传输通道一-stdio-transport" aria-label="Permalink to &quot;传输通道一：\`stdio\` Transport&quot;">​</a></h3><ul><li>适用于运行在本地操作系统中的独立脚本或工具包；</li><li>平台通过 Java ProcessBuilder 唤起本地子进程（如 Python 数据分析脚本、Node.js 爬虫工具），通过标准输入/输出流（stdin/stdout）进行 JSON-RPC 交互。</li></ul><h3 id="传输通道二-http-transport-streamable-http" tabindex="-1">传输通道二：<code>http</code> Transport (Streamable HTTP) <a class="header-anchor" href="#传输通道二-http-transport-streamable-http" aria-label="Permalink to &quot;传输通道二：\`http\` Transport (Streamable HTTP)&quot;">​</a></h3><ul><li>适用于部署在独立服务器、云端或容器集群中的远程 MCP 服务端；</li><li>基于 HTTP/SSE 长连接保持双向事件流通信，支持高并发与微服务解耦。</li></ul><hr><h2 id="_2-内置暴露的-mcp-工业工具集" tabindex="-1">2. 内置暴露的 MCP 工业工具集 <a class="header-anchor" href="#_2-内置暴露的-mcp-工业工具集" aria-label="Permalink to &quot;2. 内置暴露的 MCP 工业工具集&quot;">​</a></h2><p>MzMedia 将底座核心能力封装为标准 MCP Tools：</p><ul><li><code>iot_query_device_telemetry</code>：根据设备 ID 和时间范围查询 TDengine 中的电流、温度时序遥测数据；</li><li><code>iot_get_alert_records</code>：获取设备近期触发的未解除告警记录；</li><li><code>media_call_preset_and_snapshot</code>：调用指定国标摄像机预置位并抓取实时高清画面快照；</li><li><code>mes_create_maintenance_order</code>：根据排查结论自动在 MES 系统中创建维修工单并派发给工程师。</li></ul>`,14)])])}const _=e(s,[["render",l]]);export{m as __pageData,_ as default};
